    EmailIntegrationRequest.fromJson(Map<String, dynamic> json) { fromMap(json); }

    fromMap(Map<String, dynamic> json) {
        integrationId = json['integrationId'];
        provider = JsonConverters.fromJson(json['provider'],'EmailProvider',context!);
        integrationName = json['integrationName'] ?? "";
        isEnabled = json['isEnabled'];
        emailAddress = json['emailAddress'] ?? "";
        emailSenderName = json['emailSenderName'];
        return this;
    }

    Map<String, dynamic> toJson() => {
        'integrationId': integrationId,
        'provider': JsonConverters.toJson(provider,'EmailProvider',context!),
        'integrationName': integrationName,
        'isEnabled': isEnabled,
        'emailAddress': emailAddress,
        'emailSenderName': emailSenderName
    };

    getTypeName() => "EmailIntegrationRequest";
    TypeContext? context = _ctx;
}

