class AccountStatus
{
    static const AccountStatus Registered = const AccountStatus._(1);
    static const AccountStatus PendingValidation = const AccountStatus._(2);
    static const AccountStatus Active = const AccountStatus._(8);
    static const AccountStatus InActive = const AccountStatus._(16);
    static const AccountStatus Blocked = const AccountStatus._(32);
    static const AccountStatus Unregistered = const AccountStatus._(64);

    final int _value;
    const AccountStatus._(this._value);
    int get value => _value;
    static List<AccountStatus> get values => const [Registered,PendingValidation,Active,InActive,Blocked,Unregistered];
}

