// @Route("/{version}/account/profile", "PUT")
// @DataContract
class UpdateAccountProfile extends RequestBase implements IReturn<EmptyResponse>, IConvertible, IPut
{
    /**
    * Account owner's display name.
    */
    // @DataMember
    // @ApiMember(Description="Account owner's display name.", IsRequired=true)
    String displayName = "";

    /**
    * Email address used for billing communications.
    */
    // @DataMember
    // @ApiMember(Description="Email address used for billing communications.")
    String? billingEmail;

    /**
    * Email address used for operations communications.
    */
    // @DataMember
    // @ApiMember(Description="Email address used for operations communications.")
    String? operationsEmail;

    /**
    * Email address used for security-related communications.
    */
    // @DataMember
    // @ApiMember(Description="Email address used for security-related communications.")
    String? securityEmail;

    UpdateAccountProfile({this.displayName="",this.billingEmail,this.operationsEmail,this.securityEmail});
    UpdateAccountProfile.fromJson(Map<String, dynamic> json) { fromMap(json); }

    fromMap(Map<String, dynamic> json) {
        super.fromMap(json);
        displayName = json['displayName'] ?? "";
        billingEmail = json['billingEmail'];
        operationsEmail = json['operationsEmail'];
        securityEmail = json['securityEmail'];
        return this;
    }

    Map<String, dynamic> toJson() => super.toJson()..addAll({
        'displayName': displayName,
        'billingEmail': billingEmail,
        'operationsEmail': operationsEmail,
        'securityEmail': securityEmail
    });

    createResponse() => EmptyResponse();
    getResponseTypeName() => "EmptyResponse";
    getTypeName() => "UpdateAccountProfile";
    TypeContext? context = _ctx;
}

